import{_ as e,o as t,c as a,Q as i}from"./chunks/framework.b7a782ac.js";const m=JSON.parse('{"title":"Calling API endpoints","description":"","frontmatter":{},"headers":[],"relativePath":"getting-started/calling-api-endpoints.md","filePath":"getting-started/calling-api-endpoints.md"}'),n={name:"getting-started/calling-api-endpoints.md"},o=i('<h1 id="calling-api-endpoints" tabindex="-1">Calling API endpoints <a class="header-anchor" href="#calling-api-endpoints" aria-label="Permalink to &quot;Calling API endpoints&quot;">​</a></h1><p>Once your registration application has been approved, the connection credentials are sent to the email address you provided during registration.</p><div class="tip custom-block"><p class="custom-block-title">NOTE</p><p>The API is intended for automated integrations. To upload, flag or download fraud data manually, use the FIB Web App: it signs every request for you, and no code is needed. See <a href="./../tutorials-web.html">Tutorials: Web App</a>, for example <a href="./../tutorials-web/downloading-fraud-data.html">Downloading fraud data</a>.</p></div><p>Using these credentials, you can implement calls to the FIB API endpoints into the code of your own application or system.</p><h2 id="base-url" tabindex="-1">Base URL <a class="header-anchor" href="#base-url" aria-label="Permalink to &quot;Base URL&quot;">​</a></h2><p>Send every API request to:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki github-dark vp-code-dark"><code><span class="line"><span style="color:#e1e4e8;">https://backend.fraudintelligencelimited.com</span></span></code></pre><pre class="shiki github-light vp-code-light"><code><span class="line"><span style="color:#24292e;">https://backend.fraudintelligencelimited.com</span></span></code></pre></div><p>Endpoint paths throughout this documentation are relative to that host. For example, <a href="./../tutorials-api/authorizing-an-account.html">Authorizing an account</a> gives the path <code>POST /auth/api/v1/authentication-management/session</code>, so the full URL is <code>https://backend.fraudintelligencelimited.com/auth/api/v1/authentication-management/session</code>.</p><p>Following the basic API architecture, your application or system—the <em>API client</em> in this relationship—connects to the FIB <em>API server</em>.</p><p>To integrate your API client with the FIB API server, you can use different programming languages and frameworks, including Python, Java, Node.js, RUST, depending on the requirements of your own application or system.</p><p>Some tutorials in this documentation provide code snippets for the operations that require a signature, such as <a href="./../tutorials-api/signing-user-email-addresses.html">Signing user email addresses</a>.</p><p>The provided FIB <a href="./../api-specification.html">API endpoints</a> allow users to access the network&#39;s blockchain data, enabling users to perform operations such as <a href="./../tutorials-api/submitting-a-contribution.html">submitting</a>, <a href="./../tutorials-api/retrieving-contributions.html">retrieving</a> and <a href="./../tutorials-api/flagging-a-contribution.html">flagging contributions</a>, etc.</p><p>For examples of scenarios where FIB API endpoints are being called, check out the topics in the <a href="./../tutorials-api.html">Tutorials: API</a> section.</p><div class="tip custom-block"><p class="custom-block-title">NOTE</p><p>Certain API requests require the use of either your <a href="./../overview/web-interface.html#akp"><strong>Authorization</strong> key pair</a> or <a href="./../overview/web-interface.html#bkp"><strong>Blockchain</strong> key pair</a>.</p></div>',14),s=[o];function r(l,p,c,d,h,u){return t(),a("div",null,s)}const f=e(n,[["render",r]]);export{m as __pageData,f as default};
